-- fail-closed: never target a bypass role

-- permdock helpers (database: reads the membership and user_roles tables) sha-256:tXZ05yPoc7onCWBQbwoXnKeC9u1t4FLJX5lnVAhWSDU
-- policies call them uncorrelated, so Postgres evaluates each once per statement

create schema if not exists "permdock";
revoke all on schema "permdock" from public;
grant usage on schema "permdock" to authenticated;

-- the caller's user id: the sub of request.jwt.claims, or null when it is empty or absent
create or replace function "permdock".permdock_user_id()
returns uuid
language sql
stable
parallel safe
set search_path = ''
as $$
  select nullif(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub',
    ''
  )::uuid
$$;
revoke execute on function "permdock".permdock_user_id() from public, anon;
grant execute on function "permdock".permdock_user_id() to authenticated;

create table "permdock".role_permissions (
  role text not null,
  permission text not null,
  grant_key text not null,
  scope text not null check (scope ~ '^[a-z][a-z0-9_]*$'),
  effect text not null default 'allow' check (effect in ('allow', 'deny')),
  primary key (role, grant_key, scope)
);
alter table "permdock".role_permissions enable row level security;
revoke all on table "permdock".role_permissions from anon, authenticated, public;
create or replace function "permdock".permdock_role_grant_keys(p_scope text, p_role text)
returns setof text
language sql
stable
parallel safe
rows 10
set search_path = ''
as $$
  select rp.grant_key from "permdock".role_permissions rp where rp.role = p_role and rp.scope = p_scope
$$;
revoke execute on function "permdock".permdock_role_grant_keys(text, text) from public, anon, authenticated;

create or replace function "permdock".permdock_has(p_grant text)
returns boolean
language sql
stable
security definer
cost 1000
parallel safe
set search_path = ''
as $$
  select exists (
    select 1
    from "public"."platform_roles" ur
    cross join lateral "permdock".permdock_role_grant_keys('global', ur."role"::text) rp(grant_key)
    where ur."user_id" = (select "permdock".permdock_user_id())
      and rp.grant_key = p_grant
      and coalesce((select "permdock".permdock_user_id()) in (select s."id" from "public"."profiles" s where s."disabled_at" is null), false)
  )
$$;
revoke execute on function "permdock".permdock_has(text) from public, anon;
grant execute on function "permdock".permdock_has(text) to authenticated;

create or replace function "permdock".permitted_organization_ids(p_grant text)
returns setof text
language plpgsql
stable
security definer
cost 1000
rows 10
parallel safe
set search_path = ''
as $$
declare
  v_user_0 "public"."memberships"."user_id"%type := (select "permdock".permdock_user_id());
begin
  return query
  select (ms.id)::text
  from (
    select m."scope"::text as scope, m."scope_id"::text as id, null::jsonb as within, jsonb_agg(distinct m."role"::text order by m."role"::text) filter (where m."role"::text is not null) as roles, null::text as via, null::bigint as expires_at, null::text as granted_by, null::text as reason, null::text as member_group, null::text as managed_by, null::jsonb as seats
    from "public"."memberships" m
    where m."user_id" = v_user_0
    group by m."scope"::text, m."scope_id"::text
    having jsonb_agg(distinct m."role"::text order by m."role"::text) filter (where m."role"::text is not null) is not null
  ) ms
  cross join lateral jsonb_array_elements_text(
    case jsonb_typeof(ms.roles) when 'array' then ms.roles else '[]'::jsonb end
  ) r(role)
  cross join lateral "permdock".permdock_role_grant_keys('organization', r.role) rp(grant_key)
  where coalesce((select "permdock".permdock_user_id())::text, '') <> ''
    and ms.scope = 'organization'
    and rp.grant_key = p_grant
    and (nullif(((select auth.jwt()) ->> 'tenant_id'), '') is null or ms.id = nullif(((select auth.jwt()) ->> 'tenant_id'), ''))
    and coalesce((select "permdock".permdock_user_id()) in (select s."id" from "public"."profiles" s where s."disabled_at" is null), false)
    and coalesce((ms.id)::text in (select s."id" from "public"."organizations" s where s."disabled_at" is null), false);
end;
$$;
revoke execute on function "permdock".permitted_organization_ids(text) from public, anon;
grant execute on function "permdock".permitted_organization_ids(text) to authenticated;

