-- the permission keys a role holds on a scope, with effect allow or deny; a custom role is read for its tenant and, below the first scope, its instance
create or replace function "permdock".permdock_role_permissions(p_role text, p_scope text, p_tenant text default null, p_scope_id text default null)
returns table (permission text, effect text)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform p_tenant, p_scope_id; -- only a custom role reads them
  return query
  select distinct rp.permission, rp.effect
  from "permdock".role_permissions rp
  where rp.role = p_role and rp.scope = p_scope
  order by 1, 2;
end;
$$;
revoke execute on function "permdock".permdock_role_permissions(text, text, text, text) from public, anon;
grant execute on function "permdock".permdock_role_permissions(text, text, text, text) to authenticated;

