$$;
revoke execute on function "permdock".permitted_organization_permission_keys_for(uuid, text, text[]) from public, anon, authenticated;

-- the caller's permissions in better-supabase's compact BootstrapPermissionsWire: the policy's keys once, a bitset per organization the caller is a member of (p_tenant alone when given) and one for platform
create or replace function "permdock".permdock_bootstrap_permissions(p_tenant text default null)
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  with pdk_k(key, n) as (
    select k.key, (k.n - 1)::integer
    from unnest(array['organizations.manage', 'projects.delete', 'projects.list', 'projects.read', 'projects.update']::text[]) with ordinality as k(key, n)
  ),
  pdk_t(id) as (
    select t.id from "permdock".member_organization_ids() as t(id)
    where p_tenant is null or t.id::text = p_tenant
  ),
  pdk_p(n) as (
    select k.n from pdk_k k
    where k.key = any(array['organizations.manage']::text[]) and "permdock".permdock_has_permission(k.key)
  )
  select jsonb_strip_nulls(jsonb_build_object(
    'apiVersion', 1,
    'form', 'compact',
    'keys', to_jsonb(array['organizations.manage', 'projects.delete', 'projects.list', 'projects.read', 'projects.update']::text[]),
    'tenants', coalesce((
      select jsonb_object_agg(t.id::text, (select translate(encode(coalesce(decode(string_agg(lpad(to_hex(coalesce(b.v, 0)), 2, '0'), '' order by g.i), 'hex'), ''::bytea), 'base64'), '+/=' || chr(10), '-_')
      from generate_series(0, 0) g(i)
      left join (
        select x.n / 8 as i, sum(1 << (x.n % 8)) as v from (select k.n from "permdock".permitted_organization_permission_keys(t.id) h(key) join pdk_k k on k.key = h.key) x(n) group by 1
      ) b on b.i = g.i))
      from pdk_t t
    ), '{}'::jsonb),
    'platform', case when exists (select 1 from pdk_p) then (select translate(encode(coalesce(decode(string_agg(lpad(to_hex(coalesce(b.v, 0)), 2, '0'), '' order by g.i), 'hex'), ''::bytea), 'base64'), '+/=' || chr(10), '-_')
      from generate_series(0, 0) g(i)
      left join (
        select x.n / 8 as i, sum(1 << (x.n % 8)) as v from (select p.n from pdk_p p) x(n) group by 1
      ) b on b.i = g.i) end
  ))
$$;
revoke execute on function "permdock".permdock_bootstrap_permissions(text) from public, anon, authenticated;
grant execute on function "permdock".permdock_bootstrap_permissions(text) to authenticated;

-- the users who hold a permission on one organization: its members and the global-role holders for whom the _for helpers answer; no client role may execute it
create or replace function "permdock".permitted_organization_users(p_permission text, p_id text)
returns setof uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_key_0 "public"."memberships"."scope_id"%type := p_id;
begin
  return query
    select c.user_id
    from (
      select h.user_id::uuid
      from (
        select m."scope_id"::text as id, m."user_id"::text as user_id, m."role"::text as role, null::text as via, true as live
        from "public"."memberships" m
        where m."scope"::text = 'organization' and m."scope_id" = v_key_0
      ) h
      union
      select ur."user_id"::uuid
      from "public"."platform_roles" ur
    ) c(user_id)
    where c.user_id is not null
      and (
        p_id in (select "permdock".permitted_organization_ids_by_permission_for(c.user_id, p_permission))
        or "permdock".permdock_has_permission_for(c.user_id, p_permission)
      )
    order by 1;
end
$$;
revoke execute on function "permdock".permitted_organization_users(text, text) from public, anon, authenticated;

-- approval store: ApprovalRequest bodies, opened, resolved and consumed through the functions below; supabaseApprovalStore calls them
create table "permdock".approval_requests (
  token text primary key,
  body jsonb not null,
  status text not null check (status in ('pending', 'approved', 'rejected', 'expired')),
  tenant text,
  principal_id text,
  actor_id text,
  session text,
  approvals integer not null default 0,
  created_at text not null,
  expires_at timestamptz not null,
  consumed_at timestamptz
);
create index "approval_requests_page" on "permdock".approval_requests (created_at collate "C", token collate "C");
-- only open requests expire, so the index holds them alone
create index "approval_requests_pending_expires" on "permdock".approval_requests (expires_at) where status = 'pending';
alter table "permdock".approval_requests enable row level security;
revoke all on table "permdock".approval_requests from anon, authenticated, public;

-- open a request; a repeated ask keeps the open record and replaces only an expired one
create or replace function "permdock".permdock_approval_open(p_request jsonb)
returns void
language sql
volatile
security definer
set search_path = ''
as $$
  insert into "permdock".approval_requests as a (token, body, status, tenant, principal_id, actor_id, session, approvals, created_at, expires_at, consumed_at)
  values (
    p_request ->> 'token',
    p_request,
    p_request ->> 'status',
    p_request #>> '{subject,principal,tenant}',
    p_request #>> '{subject,principal,id}',
    p_request #>> '{subject,actor,id}',
    p_request #>> '{subject,session}',
    coalesce(jsonb_array_length(p_request -> 'approvals'), 0),
    p_request ->> 'createdAt',
    (p_request ->> 'expiresAt')::timestamptz,
    (p_request ->> 'consumedAt')::timestamptz
  )
  on conflict (token) do update
    set body = excluded.body, status = excluded.status, tenant = excluded.tenant,
      principal_id = excluded.principal_id, actor_id = excluded.actor_id, session = excluded.session,
      approvals = excluded.approvals, created_at = excluded.created_at,
      expires_at = excluded.expires_at, consumed_at = excluded.consumed_at
    where a.status = 'expired' or a.expires_at <= now()
$$;
revoke execute on function "permdock".permdock_approval_open(jsonb) from public, anon, authenticated;

create or replace function "permdock".permdock_approval_get(p_token text)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select a.body from "permdock".approval_requests a where a.token = p_token
$$;
revoke execute on function "permdock".permdock_approval_get(text) from public, anon, authenticated;

-- write a verdict over the record it was computed from: still pending, unexpired, with p_seen approvals
create or replace function "permdock".permdock_approval_resolve(p_token text, p_next jsonb, p_seen integer)
returns jsonb
language sql
volatile
security definer
set search_path = ''
as $$
  update "permdock".approval_requests a
  set body = p_next,
    status = p_next ->> 'status',
    approvals = coalesce(jsonb_array_length(p_next -> 'approvals'), 0)
  where a.token = p_token
    and a.status = 'pending'
    and a.expires_at > now()
    and a.approvals = p_seen
  returning a.body
$$;
revoke execute on function "permdock".permdock_approval_resolve(text, jsonb, integer) from public, anon, authenticated;

-- consume an approved, unexpired, unconsumed request once
create or replace function "permdock".permdock_approval_consume(p_token text, p_now text)
returns jsonb
language sql
volatile
security definer
set search_path = ''
as $$
  update "permdock".approval_requests a
  set consumed_at = p_now::timestamptz,
    body = a.body || jsonb_build_object('consumedAt', p_now)
  where a.token = p_token
    and a.status = 'approved'
    and a.consumed_at is null
    and a.expires_at > p_now::timestamptz
  returning a.body
$$;
revoke execute on function "permdock".permdock_approval_consume(text, text) from public, anon, authenticated;

-- one page in (createdAt, token) order after the cursor position
create or replace function "permdock".permdock_approval_list(p_filter jsonb, p_after_created text, p_after_token text, p_limit integer)
returns setof jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select a.body
  from "permdock".approval_requests a
  where (p_filter ->> 'status' is null or a.status = p_filter ->> 'status')
    and (p_filter ->> 'tenant' is null or a.tenant = p_filter ->> 'tenant')
    and (p_filter ->> 'principalId' is null or a.principal_id = p_filter ->> 'principalId')
    and (p_filter ->> 'actorId' is null or a.actor_id = p_filter ->> 'actorId')
    and (p_filter ->> 'session' is null or a.session = p_filter ->> 'session')
    and (p_after_created is null
      or (a.created_at collate "C", a.token collate "C") > (p_after_created collate "C", p_after_token collate "C"))
  order by a.created_at collate "C", a.token collate "C"
  limit p_limit
$$;
revoke execute on function "permdock".permdock_approval_list(jsonb, text, text, integer) from public, anon, authenticated;

create or replace function "permdock".permdock_approval_expire(p_now text)
returns integer
language sql
volatile
security definer
set search_path = ''
as $$
  with expired as (
    update "permdock".approval_requests a
    set status = 'expired', body = a.body || '{"status":"expired"}'::jsonb
    where a.status = 'pending' and a.expires_at <= p_now::timestamptz
    returning 1
  )
  select count(*)::integer from expired
$$;
revoke execute on function "permdock".permdock_approval_expire(text) from public, anon, authenticated;

-- reject every pending request the filter matches, as system:<by>
create or replace function "permdock".permdock_approval_cancel(p_filter jsonb, p_by text, p_note text, p_now text)
returns integer
language sql
volatile
security definer
set search_path = ''
as $$
  with cancelled as (
    update "permdock".approval_requests a
    set status = 'rejected',
      body = (a.body - 'note') || jsonb_strip_nulls(jsonb_build_object(
        'status', 'rejected', 'resolvedAt', p_now, 'resolvedBy', 'system:' || p_by, 'note', p_note
      ))
    where a.status = 'pending'
      and (p_filter ->> 'status' is null or a.status = p_filter ->> 'status')
      and (p_filter ->> 'tenant' is null or a.tenant = p_filter ->> 'tenant')
      and (p_filter ->> 'principalId' is null or a.principal_id = p_filter ->> 'principalId')
      and (p_filter ->> 'actorId' is null or a.actor_id = p_filter ->> 'actorId')
      and (p_filter ->> 'session' is null or a.session = p_filter ->> 'session')
    returning 1
  )
  select count(*)::integer from cancelled
$$;
revoke execute on function "permdock".permdock_approval_cancel(jsonb, text, text, text) from public, anon, authenticated;

-- approvers: whether the signed-in user matches a request's approvers.by; policies on approval views call it
create or replace function "permdock".permdock_is_approver_base(p_approvers jsonb, p_tenant text default null)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_user text := (select "permdock".permdock_user_id())::text;
begin
  if coalesce(v_user, '') = '' or p_approvers is null then
    return false;
  end if;
  if jsonb_typeof(p_approvers) = 'array' then
    if jsonb_array_length(p_approvers) = 0 then
      return false;
    end if;
    for v_item in select value from jsonb_array_elements(p_approvers) loop
      if not "permdock".permdock_is_approver_base(v_item, p_tenant) then
        return false;
      end if;
    end loop;
    return true;
  end if;
  if jsonb_typeof(p_approvers) <> 'object' then
    return false;
  end if;
  case p_approvers ->> 'kind'
    when 'user' then
      return coalesce(p_approvers ->> 'id' = v_user, false);
    when 'permission' then
      if p_tenant is null then
        return coalesce("permdock".permdock_has_permission(p_approvers ->> 'permission'), false);
      end if;
      return exists (
          select 1
          from "permdock".permitted_organization_ids_by_permission(p_approvers ->> 'permission') i(id)
          where i.id::text = p_tenant
        );
    when 'any-of' then
      if jsonb_typeof(p_approvers -> 'of') <> 'array' then
        return false;
      end if;
      for v_item in select value from jsonb_array_elements(p_approvers -> 'of') loop
        if "permdock".permdock_is_approver_base(v_item, p_tenant) then
          return true;
        end if;
      end loop;
      return false;
    else
      return false;
  end case;
end;
$$;
revoke execute on function "permdock".permdock_is_approver_base(jsonb, text) from public, anon, authenticated;

-- approval managers: whether p_user manages p_requester within p_levels steps of public.reporting_lines
create or replace function "permdock".permdock_manages_for(p_user text, p_requester text, p_levels integer, p_tenant text default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  with recursive chain (id, depth, path) as (
    select m."manager_id"::text, 1, array[p_requester, m."manager_id"::text]
    from "public"."reporting_lines" m
    where m."user_id" = p_requester::uuid
      and m."manager_id" is not null
      and m."organization_id" = p_tenant::text
    union all
    select m."manager_id"::text, c.depth + 1, c.path || m."manager_id"::text
    from chain c
    join "public"."reporting_lines" m on m."user_id" = c.id::uuid
    where c.depth < least(p_levels, 8)
      and m."manager_id" is not null
      and not (m."manager_id"::text = any (c.path))
      and m."organization_id" = p_tenant::text
  )
  select coalesce(
    p_requester <> ''
      and p_user <> ''
      and p_levels between 1 and 8
      and p_user <> p_requester
      and exists (select 1 from chain c where c.id = p_user),
    false
  )
$$;
revoke execute on function "permdock".permdock_manages_for(text, text, integer, text) from public, anon, authenticated;

-- approval managers: whether the signed-in user manages p_requester within p_levels steps of public.reporting_lines
create or replace function "permdock".permdock_manages(p_requester text, p_levels integer, p_tenant text default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select "permdock".permdock_manages_for((select "permdock".permdock_user_id())::text, p_requester, p_levels, p_tenant)
$$;
revoke execute on function "permdock".permdock_manages(text, integer, text) from public, anon, authenticated;

-- approval managers: approvers.by with manager leaves; only permdock_is_approver calls it
create or replace function "permdock".permdock_approves(p_approvers jsonb, p_tenant text, p_requester text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_levels jsonb;
begin
  if p_approvers is null then
    return false;
  end if;
  if jsonb_typeof(p_approvers) = 'array' then
    if jsonb_array_length(p_approvers) = 0 then
      return false;
    end if;
    for v_item in select value from jsonb_array_elements(p_approvers) loop
      if not "permdock".permdock_approves(v_item, p_tenant, p_requester) then
        return false;
      end if;
    end loop;
    return true;
  end if;
  if jsonb_typeof(p_approvers) <> 'object' then
    return false;
  end if;
  case p_approvers ->> 'kind'
    when 'manager' then
      v_levels := coalesce(p_approvers -> 'levels', '1'::jsonb);
      if jsonb_typeof(v_levels) <> 'number' or v_levels::text !~ '^[0-9]{1,2}$' then
        return false;
      end if;
      return coalesce("permdock".permdock_manages(p_requester, v_levels::text::integer, p_tenant), false);
    when 'any-of' then
      if jsonb_typeof(p_approvers -> 'of') <> 'array' then
        return false;
      end if;
      for v_item in select value from jsonb_array_elements(p_approvers -> 'of') loop
        if "permdock".permdock_approves(v_item, p_tenant, p_requester) then
          return true;
        end if;
      end loop;
      return false;
    else
      return "permdock".permdock_is_approver_base(p_approvers, p_tenant);
  end case;
end;
$$;
revoke execute on function "permdock".permdock_approves(jsonb, text, text) from public, anon, authenticated;

-- approvers with managers: the two-argument call decides manager leaves when it passes the requester
create or replace function "permdock".permdock_is_approver(p_approvers jsonb, p_tenant text default null, p_requester text default null)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce("permdock".permdock_approves(p_approvers, p_tenant, p_requester), false)
$$;
revoke execute on function "permdock".permdock_is_approver(jsonb, text, text) from public, anon;
grant execute on function "permdock".permdock_is_approver(jsonb, text, text) to authenticated;

-- approval delegations: out-of-office covers a user writes for themselves; tableApprovalDelegationSource and permdock_is_approver read them
create table "permdock".approval_delegations (
  id text primary key default gen_random_uuid()::text,
  delegator uuid not null default ("permdock".permdock_user_id())::uuid,
  delegate uuid not null,
  tenant text,
  permissions text[],
  resources text[],
  "from" timestamptz not null default now(),
  "until" timestamptz not null,
  created_at timestamptz not null default now(),
  constraint "approval_delegations_window" check ("from" < "until"),
  constraint "approval_delegations_distinct" check (delegator <> delegate)
);
create index "approval_delegations_delegate" on "permdock".approval_delegations (delegate, "until");
create index "approval_delegations_delegator" on "permdock".approval_delegations (delegator, "until");
alter table "permdock".approval_delegations enable row level security;
revoke all on table "permdock".approval_delegations from anon, public;
grant select, insert, update, delete on table "permdock".approval_delegations to authenticated;
create policy "approval_delegations_read" on "permdock".approval_delegations
  for select to authenticated
  using (delegator = (select "permdock".permdock_user_id())::uuid or delegate = (select "permdock".permdock_user_id())::uuid);
create policy "approval_delegations_insert" on "permdock".approval_delegations
  for insert to authenticated
  with check (delegator = (select "permdock".permdock_user_id())::uuid and (tenant is null or tenant in (select m.id::text from "permdock".member_organization_ids() m(id))));
create policy "approval_delegations_update" on "permdock".approval_delegations
  for update to authenticated
  using (delegator = (select "permdock".permdock_user_id())::uuid)
  with check (delegator = (select "permdock".permdock_user_id())::uuid and (tenant is null or tenant in (select m.id::text from "permdock".member_organization_ids() m(id))));
create policy "approval_delegations_delete" on "permdock".approval_delegations
  for delete to authenticated
  using (delegator = (select "permdock".permdock_user_id())::uuid);

-- approval delegations: whether a delegator's own rights match approvers.by; only permdock_is_approver calls it
create or replace function "permdock".permdock_cover_approves(p_delegator uuid, p_approvers jsonb, p_tenant text, p_requester text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_item jsonb;
  v_levels jsonb;
begin
  if p_delegator is null or p_approvers is null then
    return false;
  end if;
  if jsonb_typeof(p_approvers) = 'array' then
    if jsonb_array_length(p_approvers) = 0 then
      return false;
    end if;
    for v_item in select value from jsonb_array_elements(p_approvers) loop
      if not "permdock".permdock_cover_approves(p_delegator, v_item, p_tenant, p_requester) then
        return false;
      end if;
    end loop;
    return true;
  end if;
  if jsonb_typeof(p_approvers) <> 'object' then
    return false;
  end if;
  case p_approvers ->> 'kind'
    when 'user' then
      return coalesce(p_approvers ->> 'id' = p_delegator::text, false);
    when 'permission' then
      if p_tenant is null then
        return coalesce("permdock".permdock_has_permission_for(p_delegator, p_approvers ->> 'permission'), false);
      end if;
      return exists (
          select 1
          from "permdock".permitted_organization_ids_by_permission_for(p_delegator, p_approvers ->> 'permission') i(id)
          where i.id::text = p_tenant
        );
    when 'manager' then
      v_levels := coalesce(p_approvers -> 'levels', '1'::jsonb);
      if jsonb_typeof(v_levels) <> 'number' or v_levels::text !~ '^[0-9]{1,2}$' then
        return false;
      end if;
      return coalesce("permdock".permdock_manages_for(p_delegator::text, p_requester, v_levels::text::integer, p_tenant), false);
    when 'any-of' then
      if jsonb_typeof(p_approvers -> 'of') <> 'array' then
        return false;
      end if;
      for v_item in select value from jsonb_array_elements(p_approvers -> 'of') loop
        if "permdock".permdock_cover_approves(p_delegator, v_item, p_tenant, p_requester) then
          return true;
        end if;
      end loop;
      return false;
    else
      return false;
  end case;
end;
$$;
revoke execute on function "permdock".permdock_cover_approves(uuid, jsonb, text, text) from public, anon, authenticated;

-- approvers with covers: the signed-in user, or a delegate inside an active cover of a delegator who is not the requester
create or replace function "permdock".permdock_is_approver(p_approvers jsonb, p_tenant text, p_requester text, p_resource text)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_delegator uuid;
  v_user text := (select "permdock".permdock_user_id())::text;
begin
  if "permdock".permdock_approves(p_approvers, p_tenant, p_requester) then
    return true;
  end if;
  if coalesce(v_user, '') = '' or coalesce(p_requester, '') = '' then
    return false;
  end if;
  if p_tenant is not null and not (p_tenant in (select m.id::text from "permdock".member_organization_ids() m(id))) then
    return false;
  end if;
  for v_delegator in
    select d.delegator
    from "permdock".approval_delegations d
    where d.delegate = v_user::uuid
      and d.delegator::text <> v_user
      and d.delegator::text <> p_requester
      and d."from" <= now()
      and now() < d."until"
      and (d.tenant is null or d.tenant = p_tenant)
      and d.permissions is null
      and (d.resources is null or p_resource = any (d.resources))
  loop
    if "permdock".permdock_cover_approves(v_delegator, p_approvers, p_tenant, p_requester) then
      return true;
    end if;
  end loop;
  return false;
end;
$$;
revoke execute on function "permdock".permdock_is_approver(jsonb, text, text, text) from public, anon;
grant execute on function "permdock".permdock_is_approver(jsonb, text, text, text) to authenticated;

-- approvers with the current step: the four-argument check over p_approvers and the step's users, manager and permission
create or replace function "permdock".permdock_is_approver(p_approvers jsonb, p_tenant text, p_requester text, p_resource text, p_request_approvers jsonb)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select "permdock".permdock_is_approver(
    jsonb_build_object(
      'kind', 'any-of',
      'of',
      case when p_approvers is null then '[]'::jsonb else jsonb_build_array(p_approvers) end
        || case
          when jsonb_typeof(p_request_approvers -> 'users') = 'array' then coalesce(
            (select jsonb_agg(jsonb_build_object('kind', 'user', 'id', u.id)) from jsonb_array_elements_text(p_request_approvers -> 'users') u(id)),
            '[]'::jsonb
          )
          else '[]'::jsonb
        end
        || case when p_request_approvers -> 'manager' = 'true'::jsonb then '[{"kind": "manager"}]'::jsonb else '[]'::jsonb end
        || case
          when jsonb_typeof(p_request_approvers -> 'permission') = 'string'
            then jsonb_build_array(jsonb_build_object('kind', 'permission', 'permission', p_request_approvers ->> 'permission'))
          else '[]'::jsonb
        end
    ),
    p_tenant,
    p_requester,
    p_resource
  )
$$;
revoke execute on function "permdock".permdock_is_approver(jsonb, text, text, text, jsonb) from public, anon;
grant execute on function "permdock".permdock_is_approver(jsonb, text, text, text, jsonb) to authenticated;

