returns setof uuid
language sql
stable
security definer
cost 1000
rows 50
parallel safe
set search_path = ''
as $$
  with recursive down (id, depth, path) as (
    select m."user_id", 1, array[(select "permdock".permdock_user_id()), m."user_id"]
    from "public"."reporting_lines" m
    where m."manager_id" = (select "permdock".permdock_user_id())
      and m."user_id" is not null
      and m."user_id" <> (select "permdock".permdock_user_id())
      and m."organization_id" = p_tenant
